package com.quizrank.backend.controller;
import com.quizrank.backend.entity.AcademicRecord;import com.quizrank.backend.repository.AcademicRecordRepository;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/academic-records") public class AcademicRecordController {private final AcademicRecordRepository r;public AcademicRecordController(AcademicRecordRepository r){this.r=r;}@GetMapping("/student/{id}") public List<AcademicRecord> student(@PathVariable Integer id){return r.findByStudentIdOrderByIdDesc(id);}@GetMapping("/student/{id}/current") public AcademicRecord current(@PathVariable Integer id){return r.findFirstByStudentIdAndSemester(id,"Current").orElseThrow(()->new NoSuchElementException("Current academic record not found"));}}
